                case "jsonl":
                    self = .jsonl(try container.decode(CreateEvalJsonlRunDataSource.self))
                    return
                case "completions":
                    self = .completions(try container.decode(CreateEvalCompletionsRunDataSource.self))
                    return
                case "responses":
                    self = .responses(try container.decode(CreateEvalResponsesRunDataSource.self))
                    return
                default:
                    break
